const input = $input.first().json || {};
const documentId = String(input.documentId || '');
const question = String(input.question || '');
const workspaceId = String(input.workspaceId || '');

function httpStatus(res) {
  return res && res.statusCode !== undefined ? res.statusCode : res && res.status;
}

async function embed(text) {
  const res = await $http.request({
    method: 'POST',
    url: `${$env.EMBEDDING_BASE_URL}/embeddings`,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${$env.EMBEDDING_API_KEY}`,
    },
    body: { model: $env.EMBEDDING_MODEL, input: text },
  });
  if (httpStatus(res) >= 400) {
    throw new Error(`Embedding request failed (${httpStatus(res)}): ${JSON.stringify(res.body || {})}`);
  }
  const data = res.body && res.body.data;
  if (!data || !data.length || !Array.isArray(data[0].embedding)) {
    throw new Error('Embedding response did not contain a valid vector');
  }
  return data[0].embedding;
}

async function search(vector) {
  const res = await $http.request({
    method: 'POST',
    url: `${$env.QDRANT_URL}/collections/careeros_pdf_chunks/points/search`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      vector,
      limit: 5,
      with_payload: true,
      filter: {
        must: [{ key: 'document_id', match: { value: documentId } }],
      },
    },
  });
  if (httpStatus(res) >= 400) {
    throw new Error(`Qdrant search failed (${httpStatus(res)}): ${JSON.stringify(res.body || {})}`);
  }
  return res.body && Array.isArray(res.body.result) ? res.body.result : [];
}

async function askLlm(messages) {
  const res = await $http.request({
    method: 'POST',
    url: `${$env.LLM_BASE_URL}/chat/completions`,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${$env.LLM_API_KEY}`,
    },
    body: { model: $env.LLM_MODEL, temperature: 0, messages },
  });
  if (httpStatus(res) >= 400) {
    throw new Error(`LLM request failed (${httpStatus(res)}): ${JSON.stringify(res.body || {})}`);
  }
  const choice = res.body && res.body.choices && res.body.choices[0];
  if (!choice || !choice.message || typeof choice.message.content !== 'string') {
    throw new Error('LLM response did not contain message content');
  }
  return choice.message.content;
}

try {
  if (!documentId || !question) {
    return [{ json: { answer: 'An error occurred while processing your question.', sources: [] } }];
  }

  const vector = await embed(question);
  const hits = await search(vector);

  const sources = [];
  if (!hits.length) {
    return [{ json: { answer: 'The information is not available in the uploaded document.', sources: [] } }];
  }

  const context = hits
    .map((hit) => {
      const payload = hit.payload || {};
      const pageNumber = typeof payload.page === 'number' ? payload.page : 0;
      const content = payload.text != null ? String(payload.text) : '';
      sources.push({
        pageNumber,
        score: typeof hit.score === 'number' ? hit.score : 0,
        content,
      });
      return `[Page ${pageNumber}] ${content}`;
    })
    .join('\n\n');

  const prompt =
    'You are an AI tutor.\n' +
    'Use ONLY the retrieved document context below to answer.\n' +
    'If the answer is not found, clearly state that the information is not available in the uploaded document.\n' +
    'Do not hallucinate.\n' +
    'Provide concise, accurate explanations.\n' +
    'When possible include the source page number.\n\n' +
    `Context:\n${context}\n\n` +
    `Question: ${question}\n\n` +
    'Answer:';

  const answer = (await askLlm([{ role: 'user', content: prompt }])).trim();
  return [{ json: { answer, sources } }];
} catch (e) {
  return [{ json: { answer: 'An error occurred while processing your question.', sources: [] } }];
}
